"""
MailMind State Definition
Defines the shared state schema for LangGraph agent orchestration.
"""

from typing import Annotated, TypedDict, List, Dict, Any, Optional, Literal
from langgraph.graph.message import add_messages


class PlanStep(TypedDict):
    """Represents an atomic task generated by the Planner."""
    step_id: int
    tool: Literal["gmail", "calendar", "rag", "memory"]
    action: str
    args: Dict[str, Any]
    status: Literal["pending", "running", "completed", "failed"]
    result: Optional[str]


class CitationSource(TypedDict):
    """Source reference for evidence verification."""
    source_type: Literal["gmail", "calendar", "memory"]
    id: str
    title: str
    timestamp: str
    snippet: str
    url: Optional[str]


class MailMindState(TypedDict):
    """
    Unified state for MailMind LangGraph workflow.
    Uses add_messages reducer for conversational continuity.
    """
    # Conversational messages
    messages: Annotated[list, add_messages]
    
    # User context & authentication
    user_id: str
    thread_id: str
    user_preferences: Dict[str, Any]
    
    # Task planning
    plan: List[PlanStep]
    current_step_index: int
    needs_replanning: bool
    
    # Evidence & retrieved sources
    retrieved_emails: List[Dict[str, Any]]
    retrieved_events: List[Dict[str, Any]]
    retrieved_memories: List[Dict[str, Any]]
    citations: List[CitationSource]
    
    # Human-in-the-Loop approval gate
    pending_action: Optional[Dict[str, Any]]
    action_approved: Optional[bool]
    user_feedback: Optional[str]
    
    # Final synthesized response
    final_response: Optional[str]
